 public static void Ensure(){foreach(string path in new[]{"Assets/Resources/Art/RepairAtlas.png","Assets/Resources/Art/WorldMaterialsAtlas.png","Assets/Resources/Art/TreeCanopy.png","Assets/Resources/Art/SkyPanorama.png","Assets/Resources/Art/RepairEmpireIcon.png"}){var texture=AssetImporter.GetAtPath(path) as TextureImporter;if(texture==null)continue;texture.textureShape=TextureImporterShape.Texture2D;texture.maxTextureSize=2048;texture.mipmapEnabled=true;texture.anisoLevel=4;texture.alphaIsTransparency=path.Contains("TreeCanopy");texture.isReadable=path.Contains("WorldMaterials");texture.textureCompression=path.Contains("WorldMaterials")?TextureImporterCompression.Uncompressed:TextureImporterCompression.Compressed;texture.wrapMode=path.Contains("Atlas")?TextureWrapMode.Clamp:TextureWrapMode.Repeat;texture.SaveAndReimport();}EnsureWorkshopSurfaces();EnsureWorkshopArtwork();EnsureStreetSurfaces();EnsureServiceSurfaces();EnsureWorldArray();var icon=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/Art/RepairEmpireIcon.png");if(icon!=null)PlayerSettings.SetIconsForTargetGroup(BuildTargetGroup.Unknown,new[]{icon});AssetDatabase.SaveAssets();}
 static void EnsureServiceSurfaces(){foreach(string path in new[]{"Assets/Resources/Art/ServiceStone-v1.png","Assets/Resources/Art/ServiceCloth-v1.png"}){var texture=AssetImporter.GetAtPath(path) as TextureImporter;if(texture==null)throw new System.InvalidOperationException("Missing original service surface: "+path);texture.textureType=TextureImporterType.Default;texture.textureShape=TextureImporterShape.Texture2D;texture.maxTextureSize=256;texture.mipmapEnabled=true;texture.anisoLevel=2;texture.isReadable=false;texture.sRGBTexture=true;texture.alphaIsTransparency=false;texture.wrapMode=TextureWrapMode.Repeat;texture.filterMode=FilterMode.Trilinear;texture.textureCompression=TextureImporterCompression.CompressedHQ;texture.SaveAndReimport();}}
 static void EnsureStreetSurfaces(){foreach(string path in new[]{"Assets/Resources/Art/StreetBrick-v1.png","Assets/Resources/Art/StreetLeafSprigs-v1.png"}){var texture=AssetImporter.GetAtPath(path) as TextureImporter;if(texture==null)throw new System.InvalidOperationException("Missing original street surface: "+path);bool foliage=path.Contains("LeafSprigs");texture.textureType=TextureImporterType.Default;texture.textureShape=TextureImporterShape.Texture2D;texture.maxTextureSize=512;texture.mipmapEnabled=true;texture.mipMapsPreserveCoverage=foliage;texture.alphaTestReferenceValue=.42f;texture.anisoLevel=4;texture.isReadable=false;texture.sRGBTexture=true;texture.alphaIsTransparency=foliage;texture.wrapMode=foliage?TextureWrapMode.Clamp:TextureWrapMode.Repeat;texture.filterMode=FilterMode.Trilinear;texture.textureCompression=TextureImporterCompression.CompressedHQ;texture.SaveAndReimport();}}
 static void EnsureWorkshopArtwork(){foreach(string path in new[]{"Assets/Resources/Art/Workshop/ServiceWorkshopHero-v1.png","Assets/Resources/Art/Workshop/ServiceWorkshopHero-wide-v1.png"}){var texture=AssetImporter.GetAtPath(path) as TextureImporter;if(texture==null)throw new System.InvalidOperationException("Missing original menu artwork: "+path);texture.textureType=TextureImporterType.Default;texture.textureShape=TextureImporterShape.Texture2D;texture.maxTextureSize=2048;texture.npotScale=TextureImporterNPOTScale.None;texture.mipmapEnabled=false;texture.isReadable=false;texture.sRGBTexture=true;texture.alphaIsTransparency=false;texture.wrapMode=TextureWrapMode.Clamp;texture.filterMode=FilterMode.Bilinear;texture.textureCompression=TextureImporterCompression.CompressedHQ;texture.SaveAndReimport();}}
 static void EnsureWorkshopSurfaces(){foreach(string path in new[]{"Assets/Resources/Art/Workshop/Plaster.png","Assets/Resources/Art/Workshop/Oak.png"}){var texture=AssetImporter.GetAtPath(path) as TextureImporter;if(texture==null)throw new System.InvalidOperationException("Missing original workshop surface: "+path);texture.textureType=TextureImporterType.Default;texture.maxTextureSize=1024;texture.mipmapEnabled=true;texture.anisoLevel=2;texture.isReadable=false;texture.sRGBTexture=true;texture.alphaIsTransparency=false;texture.wrapMode=TextureWrapMode.Repeat;texture.filterMode=FilterMode.Trilinear;texture.textureCompression=TextureImporterCompression.CompressedHQ;texture.SaveAndReimport();}}
 static void EnsureWorldArray(){const string sourcePath="Assets/Resources/Art/WorldMaterialsAtlas.png",arrayPath="Assets/Resources/Art/WorldSurfaceArray.asset";var source=AssetDatabase.LoadAssetAtPath<Texture2D>(sourcePath);if(source==null)return;string hash=AssetDatabase.GetAssetDependencyHash(sourcePath).ToString();var previous=AssetDatabase.LoadAssetAtPath<Texture2DArray>(arrayPath);if(previous!=null&&AssetImporter.GetAtPath(arrayPath).userData==hash)return;int side=source.width/2;var array=new Texture2DArray(side,side,4,TextureFormat.RGBA32,true,false){name="WorldSurfaceArray",wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear,anisoLevel=4};for(int tile=0;tile<4;tile++)array.SetPixels(source.GetPixels((tile%2)*side,tile<2?side:0,side,side),tile);array.Apply(true,true);if(previous==null)AssetDatabase.CreateAsset(array,arrayPath);else{EditorUtility.CopySerialized(array,previous);EditorUtility.SetDirty(previous);Object.DestroyImmediate(array);}AssetDatabase.SaveAssets();var importer=AssetImporter.GetAtPath(arrayPath);importer.userData=hash;importer.SaveAndReimport();}
